namespace App\Filament\Exports;

use App\Models\Complaint;
use Filament\Actions\Exports\ExportColumn;
use Filament\Actions\Exports\Exporter;
use Filament\Actions\Exports\Models\Export;
use Illuminate\Support\Number;

/**
 * Generated exporter for Complaints records (CSV/XLSX).
 */
class ComplaintExporter extends Exporter
{
    protected static ?string $model = Complaint::class;

    /**
     * Columns included in the export.
     * @return  array  Export column definitions.
     */
    public static function getColumns(): array
    {
        return [
                        ExportColumn::make('id')->limit(50)->label('Id'),
            ExportColumn::make('txt_plain')->limit(50)->label('Full Name'),
            ExportColumn::make('txt_email')->limit(50)->label('Email'),
            ExportColumn::make('txt_area')->limit(50)->label('Description'),
            ExportColumn::make('txt_rich')->limit(50)->label('Rich Details'),
            ExportColumn::make('bool_urgent')->limit(50)->label('Urgent'),
            ExportColumn::make('opt_category')->limit(50)->label('Category'),
            ExportColumn::make('opt_channels')->limit(50)->label('Contact Channels'),
            ExportColumn::make('opt_priority')->limit(50)->label('Priority'),
            ExportColumn::make('character.nama_watak')->limit(50)->label('Nama Watak'),
            ExportColumn::make('character.nama_watak')->limit(50)->label('Nama Watak'),
            ExportColumn::make('rep_notes')->limit(50)->listAsJson()->label('Extra Notes'),
            ExportColumn::make('num_amount')->limit(50)->label('Claim Amount'),
            ExportColumn::make('dt_event')->limit(50)->label('Event Date'),
            ExportColumn::make('dt_report')->limit(50)->label('Report Datetime'),
            ExportColumn::make('aduan_status')->limit(50)->label('Status'),
            ExportColumn::make('img_proof')->limit(50)->label('Photo Evidence'),
            ExportColumn::make('doc_form')->limit(50)->label('Supporting Doc'),
            ExportColumn::make('files_extra')->limit(50)->label('Extra Attachments'),
            ExportColumn::make('map_place')->limit(50)->label('Location (embed)'),
            ExportColumn::make('vid_evidence')->limit(50)->label('Video (embed)'),
            ExportColumn::make('internal_note')->limit(50)->label('Internal Note'),
        ];
    }

    /**
     * Notification body shown when the export finishes.
     *
     * @param  Export  $export  The completed export job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Export $export): string
    {
        $body = 'Your Complaints export has completed and ' . Number::format($export->successful_rows) . ' ' . str('row')->plural($export->successful_rows) . ' exported.';

        if ($failedRowsCount = $export->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to export.';
        }

        return $body;
    }
}
